create extension if not exists pgcrypto;
create type product_type as enum ('essential','comfort','plus');
create type unit_gender as enum ('male','female');
create type bed_status as enum ('available','reserved','occupied','maintenance');
create table areas(id uuid primary key default gen_random_uuid(),name_en text not null,name_ar text,slug text unique not null);
create table properties(id uuid primary key default gen_random_uuid(),area_id uuid references areas(id),code text unique not null,slug text unique not null,name text not null,product product_type not null,gender unit_gender not null,address text,area_sqm int,bathrooms int default 2,description text,status text default 'active',created_at timestamptz default now());
create table rooms(id uuid primary key default gen_random_uuid(),property_id uuid references properties(id) on delete cascade,code text not null,room_type text not null check(room_type in('private','double','triple')),structure_type text not null check(structure_type in('original','partition')),base_monthly_price numeric(12,2) not null,ensuite boolean default false);
create table beds(id uuid primary key default gen_random_uuid(),room_id uuid references rooms(id) on delete cascade,code text not null,status bed_status default 'available');
create table profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,phone text,gender unit_gender,id_type text,id_number text,emergency_contact text,preferred_language text not null default 'ar' check(preferred_language in('ar','en')),is_unit_representative boolean not null default false,role text default 'resident' check(role in('resident','staff','area_manager','admin')));
create table bookings(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id),bed_id uuid references beds(id),move_in_date date not null,duration_months int not null,monthly_price numeric(12,2) not null,deposit_amount numeric(12,2) default 0,status text default 'pending',created_at timestamptz default now());
create table contracts(id uuid primary key default gen_random_uuid(),booking_id uuid references bookings(id) on delete cascade,start_date date,end_date date,status text default 'draft',document_path text);
create table payments(id uuid primary key default gen_random_uuid(),booking_id uuid references bookings(id),user_id uuid references profiles(id),type text check(type in('rent','deposit','fee','refund')),amount numeric(12,2) not null,due_date date,paid_at timestamptz,status text default 'pending',payment_method text);
create table maintenance_requests(id uuid primary key default gen_random_uuid(),property_id uuid references properties(id),room_id uuid references rooms(id),bed_id uuid references beds(id),user_id uuid references profiles(id),category text,title text not null,description text,priority text default 'normal',status text default 'submitted',created_at timestamptz default now(),resolved_at timestamptz);
create table property_images(id uuid primary key default gen_random_uuid(),property_id uuid references properties(id) on delete cascade,storage_path text not null,alt_text text,sort_order int default 0,is_cover boolean default false);
create table amenities(id uuid primary key default gen_random_uuid(),name text unique not null);
create table property_amenities(property_id uuid references properties(id) on delete cascade,amenity_id uuid references amenities(id) on delete cascade,primary key(property_id,amenity_id));
create table pricing_rules(id uuid primary key default gen_random_uuid(),property_id uuid references properties(id),room_id uuid references rooms(id),duration_months int not null,monthly_price numeric(12,2) not null,deposit_months numeric(4,2) default 1);
